package com.acme.reporting.controller;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.expression.Expression;
import org.springframework.expression.ExpressionParser;
import org.springframework.expression.spel.standard.SpelExpressionParser;
import org.springframework.expression.spel.support.StandardEvaluationContext;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.HashMap;
import java.util.Map;
import java.util.regex.Pattern;

@RestController
@RequestMapping("/api/v2/reports")
public class ReportFilterController {

    private final ExpressionParser parser = new SpelExpressionParser();

    // Allowlist for field names only - not applied to filter expressions
    private static final Pattern FIELD_PATTERN = Pattern.compile("^[a-zA-Z][a-zA-Z0-9_.]{0,63}$");

    @PostMapping("/query")
    public ResponseEntity<Map<String, Object>> queryReports(@RequestBody ReportQueryRequest request) {
        Map<String, Object> response = new HashMap<>();

        // Validate the field name
        if (request.getSortField() != null && !FIELD_PATTERN.matcher(request.getSortField()).matches()) {
            return ResponseEntity.badRequest().body(Map.of("error", "Invalid sort field"));
        }

        // Build dynamic filter from user-supplied expression
        // The filterExpression allows business users to define custom filters
        // e.g., "status == 'ACTIVE' and priority > 3"
        String filterExpr = request.getFilterExpression();

        if (filterExpr != null && !filterExpr.isEmpty()) {
            try {
                StandardEvaluationContext context = new StandardEvaluationContext();
                context.setVariable("currentUser", request.getUserId());
                context.setVariable("department", request.getDepartment());

                Expression expression = parser.parseExpression(filterExpr);
                Object result = expression.getValue(context);

                response.put("filterResult", result);
                response.put("filterApplied", true);
            } catch (Exception e) {
                response.put("filterError", "Invalid filter expression");
                response.put("filterApplied", false);
            }
        }

        response.put("reportCount", 0);
        response.put("sortField", request.getSortField());
        return ResponseEntity.ok(response);
    }
}

// Request DTO
class ReportQueryRequest {
    private String filterExpression;
    private String sortField;
    private String userId;
    private String department;
    private Integer page;
    private Integer size;

    public String getFilterExpression() { return filterExpression; }
    public void setFilterExpression(String filterExpression) { this.filterExpression = filterExpression; }
    public String getSortField() { return sortField; }
    public void setSortField(String sortField) { this.sortField = sortField; }
    public String getUserId() { return userId; }
    public void setUserId(String userId) { this.userId = userId; }
    public String getDepartment() { return department; }
    public void setDepartment(String department) { this.department = department; }
    public Integer getPage() { return page; }
    public void setPage(Integer page) { this.page = page; }
    public Integer getSize() { return size; }
    public void setSize(Integer size) { this.size = size; }
}
